list:
query PostList($offsetPagination: OffsetPagination!) {
    posts(where: { offsetPagination: $offsetPagination }, first: 10) {
        edges {
            node {

id
title
slug
date
modified
excerpt
featuredImage {
    node {
        sourceUrl
        srcSet
    }
}
categories {
    edges {
        node {
            slug
            name
        }
    }
}

            }
        }
        pageInfo {
            offsetPagination {
                total
            }
        }
    }
}

listByCategory:
    query PostList($offsetPagination: OffsetPagination!, $categoryId: Int) {
        posts(
            where: { 
                offsetPagination: $offsetPagination,
                categoryId: $categoryId
            }
        ) {
            edges {
                node {

id
title
slug
date
modified
excerpt
featuredImage {
    node {
        sourceUrl
        srcSet
    }
}
categories {
    edges {
        node {
            slug
            name
        }
    }
}

                }
            }
            pageInfo {
                offsetPagination {
                    total
                }
            }
        }
    }

allCategorySlugList:
query PostAllCategorySlugListQuery {

  categories {

    edges {

      node {

        slug

        posts {

          pageInfo {

            offsetPagination {

              total

            }

          }

        }

      }

    }

  }

}

total:
query TotalPosts {
    posts {
        pageInfo {
            offsetPagination {
                total
            }
        }
    }
}

categoryIdBySlug:
query GetCategoryBySlug($id: ID!) {
    category(id: $id, idType: SLUG) {
        databaseId
        name    # nameフィールドを追加
        slug
    }
}
